def switch(host_snapshot, target_templateid, target_version):
    hostid = host_snapshot['host']['hostid']
    steps = [{'method': 'host.update', 'params': {'hostid': hostid,
                                               'templates': [{'templateid': target_templateid}]}}]
    for row in host_snapshot['items']:
